document.addEventListener("DOMContentLoaded", () => {
    const sidebar = document.getElementById("sidebar");
    const toggleSidebarBtn = document.getElementById("toggleSidebar");
    const tabsTrack = document.getElementById("tabsTrack");
    const frame = document.getElementById("linkFrame");
    const mainIframeContainer = document.getElementById("mainIframeContainer");
    const currentTabTitle = document.getElementById("currentTabTitle");
    const fullscreenToggleBtn = document.getElementById("fullscreenToggleBtn");
    const fullscreenIcon = document.getElementById("fullscreenIcon");
    const fullscreenText = document.getElementById("fullscreenText");
    const mainExitFullscreenBtn = document.getElementById("mainExitFullscreenBtn");
    const loadingOverlay = document.getElementById("loadingOverlay");
    const emptyState = document.getElementById("emptyState");
    const themeToggleBtn = document.getElementById("themeToggle");
    const themeIcon = document.getElementById("themeIcon");
    const sidebarSearch = document.getElementById("sidebarSearch");

    const rightSidebar = document.getElementById("rightSidebar");
    const toggleRightSidebarBtn = document.getElementById("toggleRightSidebar");
    const rightSidebarVisibilityBtn = document.getElementById("rightSidebarVisibility");
    const rightTabsTrack = document.getElementById("rightTabsTrack");
    const rightSidebarSearch = document.getElementById("rightSidebarSearch");
    const rightLinkModal = document.getElementById("rightLinkModal");
    const rightModalIcon = document.getElementById("rightModalIcon");
    const rightModalTitle = document.getElementById("rightModalTitle");
    const closeRightLinkModalBtn = document.getElementById("closeRightLinkModal");
    const rightModalLoading = document.getElementById("rightModalLoading");
    const rightLinkFrame = document.getElementById("rightLinkFrame");

    let currentActiveIndex = 0;

    toggleSidebarBtn.addEventListener("click", () => {
        sidebar.classList.toggle("collapsed");
    });

    // Theme Switcher
    function initTheme() {
        const savedTheme = localStorage.getItem("app-theme") || "dark";
        document.documentElement.setAttribute("data-theme", savedTheme);
        themeIcon.textContent = savedTheme === "dark" ? "☾" : "☀";
    }

    themeToggleBtn.addEventListener("click", () => {
        const currentTheme = document.documentElement.getAttribute("data-theme");
        const newTheme = currentTheme === "dark" ? "light" : "dark";
        document.documentElement.setAttribute("data-theme", newTheme);
        localStorage.setItem("app-theme", newTheme);
        themeIcon.textContent = newTheme === "dark" ? "☾" : "☀";
    });
    initTheme();

    // Main Frame Fullscreen Logic & Exit Buttons
    fullscreenToggleBtn.addEventListener("click", () => {
        if (!document.fullscreenElement) {
            mainIframeContainer.requestFullscreen().catch(err => {
                alert(`Error: ${err.message}`);
            });
        } else {
            document.exitFullscreen();
        }
    });

    mainExitFullscreenBtn.addEventListener("click", () => {
        if (document.fullscreenElement) {
            document.exitFullscreen();
        }
    });

    document.addEventListener("fullscreenchange", () => {
        if (document.fullscreenElement) {
            fullscreenIcon.textContent = "✕";
            fullscreenText.textContent = "Exit Screen";
        } else {
            fullscreenIcon.textContent = "⛶";
            fullscreenText.textContent = "Full Screen";
        }
    });

    // Render Left Tabs with Search Filter
    function renderTabs(filterText = "") {
        tabsTrack.innerHTML = "";
        const filteredLinks = links.map((item, originalIndex) => ({ ...item, originalIndex }))
                                   .filter(item => item.title.toLowerCase().includes(filterText.toLowerCase()));

        if (filteredLinks.length === 0) {
            tabsTrack.innerHTML = `<div style="padding: 10px; color: var(--text-muted); font-size: 13px; text-align: center;">No matches found</div>`;
            return;
        }

        filteredLinks.forEach((link) => {
            const button = document.createElement("button");
            button.className = "link-tab" + (link.originalIndex === currentActiveIndex ? " active" : "");
            button.role = "tab";
            button.id = `tab-${link.id || link.originalIndex}`;
            button.setAttribute("aria-selected", link.originalIndex === currentActiveIndex ? "true" : "false");
            button.title = link.title;
            button.innerHTML = `
                <span class="tab-icon">${link.icon || "🔗"}</span>
                <span class="tab-title">${link.title}</span>
            `;
            button.addEventListener("click", () => switchTab(link.originalIndex));
            tabsTrack.appendChild(button);
        });
    }

    sidebarSearch.addEventListener("input", (e) => {
        renderTabs(e.target.value);
    });

    function switchTab(index, updateHash = true) {
        if (index < 0 || index >= links.length) return;
        currentActiveIndex = index;
        const selectedData = links[index];

        const allTabs = tabsTrack.querySelectorAll(".link-tab");
        allTabs.forEach(tab => {
            if (tab.id === `tab-${selectedData.id || index}`) {
                tab.classList.add("active");
                tab.setAttribute("aria-selected", "true");
            } else {
                tab.classList.remove("active");
                tab.setAttribute("aria-selected", "false");
            }
        });

        currentTabTitle.textContent = selectedData.title;
        loadingOverlay.classList.add("active");
        frame.src = selectedData.url;

        if (updateHash) {
            const slug = selectedData.id || `link-${index + 1}`;
            history.replaceState(null, "", `#${slug}`);
        }
    }

    frame.addEventListener("load", () => {
        loadingOverlay.classList.remove("active");
    });

    function handleInitialHash() {
        const hash = window.location.hash.replace("#", "");
        if (hash) {
            const foundIndex = links.findIndex((item, idx) => (item.id || `link-${idx + 1}`) === hash);
            if (foundIndex !== -1) {
                switchTab(foundIndex, false);
                return;
            }
        }
        switchTab(0, false);
    }

    if (!links || links.length === 0) {
        tabsTrack.innerHTML = "";
        frame.style.display = "none";
        emptyState.classList.add("active");
        loadingOverlay.classList.remove("active");
        currentTabTitle.textContent = "No Content";
        fullscreenToggleBtn.style.display = "none";
    } else {
        renderTabs();
        handleInitialHash();
    }

    // Right Sidebar Controls
    function initRightSidebarState() {
        const savedState = localStorage.getItem("right-sidebar-state") || "expanded";
        const savedVisibility = localStorage.getItem("right-sidebar-visible") || "true";
        if (savedVisibility === "false") {
            setRightSidebarVisibility(false);
        } else {
            setRightSidebarVisibility(true);
            setRightSidebarCollapsed(savedState === "collapsed");
        }
    }

    function setRightSidebarCollapsed(collapsed) {
        if (collapsed) {
            rightSidebar.classList.add("collapsed");
            toggleRightSidebarBtn.textContent = "›";
            toggleRightSidebarBtn.title = "Expand Right Sidebar";
            if (!rightSidebar.classList.contains("hidden-sidebar")) localStorage.setItem("right-sidebar-state", "collapsed");
        } else {
            rightSidebar.classList.remove("collapsed");
            toggleRightSidebarBtn.textContent = "‹";
            toggleRightSidebarBtn.title = "Minimize Right Sidebar";
            if (!rightSidebar.classList.contains("hidden-sidebar")) localStorage.setItem("right-sidebar-state", "expanded");
        }
    }

    function setRightSidebarVisibility(visible) {
        if (visible) {
            rightSidebar.classList.remove("hidden-sidebar");
            rightSidebarVisibilityBtn.classList.add("on");
            rightSidebarVisibilityBtn.title = "Hide Right Sidebar";
            localStorage.setItem("right-sidebar-visible", "true");
            const savedState = localStorage.getItem("right-sidebar-state") || "expanded";
            setRightSidebarCollapsed(savedState === "collapsed");
        } else {
            rightSidebar.classList.add("hidden-sidebar");
            rightSidebarVisibilityBtn.classList.remove("on");
            rightSidebarVisibilityBtn.title = "Show Right Sidebar";
            localStorage.setItem("right-sidebar-visible", "false");
            localStorage.setItem("right-sidebar-state", "hidden");
        }
    }

    toggleRightSidebarBtn.addEventListener("click", () => {
        setRightSidebarCollapsed(!rightSidebar.classList.contains("collapsed"));
    });

    rightSidebarVisibilityBtn.addEventListener("click", () => {
        setRightSidebarVisibility(!rightSidebarVisibilityBtn.classList.contains("on"));
    });

    // Render Right Tabs with Search Filter
    function renderRightLinks(filterText = "") {
        rightTabsTrack.innerHTML = "";
        if (!rightLinks || rightLinks.length === 0) return;
        
        const filteredRightLinks = rightLinks.filter(item => item.title.toLowerCase().includes(filterText.toLowerCase()));

        if (filteredRightLinks.length === 0) {
            rightTabsTrack.innerHTML = `<div style="padding: 10px; color: var(--text-muted); font-size: 13px; text-align: center;">No matches found</div>`;
            return;
        }

        filteredRightLinks.forEach((link) => {
            const button = document.createElement("button");
            button.className = "right-link-item";
            button.title = link.title;
            button.innerHTML = `
                <span class="tab-icon">${link.icon || "🔗"}</span>
                <span class="tab-title">${link.title}</span>
            `;
            button.addEventListener("click", () => {
                button.classList.add("clicked-active");
                setTimeout(() => button.classList.remove("clicked-active"), 300);
                openRightLink(link);
            });
            rightTabsTrack.appendChild(button);
        });
    }

    rightSidebarSearch.addEventListener("input", (e) => {
        renderRightLinks(e.target.value);
    });

    renderRightLinks();
    initRightSidebarState();

    function openRightLink(link) {
        rightLinkModal.classList.add("active");
        rightModalIcon.textContent = link.icon || "🔗";
        rightModalTitle.textContent = link.title;
        rightModalLoading.classList.remove("hidden");
        rightLinkFrame.src = link.url;
        document.body.classList.add("modal-open");
    }

    function closeRightLinkModal() {
        rightLinkModal.classList.remove("active");
        rightLinkFrame.src = "about:blank";
        document.body.classList.remove("modal-open");
        rightModalLoading.classList.remove("hidden");
    }

    rightLinkFrame.addEventListener("load", () => {
        if (rightLinkFrame.src !== "about:blank" && rightLinkFrame.src !== "") {
            rightModalLoading.classList.add("hidden");
        }
    });

    closeRightLinkModalBtn.addEventListener("click", closeRightLinkModal);
    
    document.addEventListener("keydown", (e) => {
        if (e.key === "Escape") {
            if (rightLinkModal.classList.contains("active")) {
                closeRightLinkModal();
            }
        }
    });
});